/// `connectorBrandColor`
pub fn brand_color(id: &str) -> Option<u32> {
    MARKS
        .iter()
        .find(|(mark, _, _)| *mark == id)
        .and_then(|(_, color, _)| *color)
}

/// The mark as an SVG asset (`connectors/<id>.svg`), filled by the text color.
pub fn svg(path: &str) -> Option<String> {
    let id = path.strip_prefix("connectors/")?.strip_suffix(".svg")?;
    let (_, _, d) = MARKS.iter().find(|(mark, _, _)| *mark == id)?;
    Some(format!(
        r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="{d}"/></svg>"#
    ))
}
